function translate(data,path){if(!data||typeof data!=="object")return data;if(Array.isArray(data.matches))return {...data,matches:data.matches.map(translatedMatch)};if(path.includes("/news/")&&Array.isArray(data.items))return {...data,windowLabel:"Latest verified football reports for "+(data.date||"today")+" (Myanmar Time)",items:data.items.map(n=>{const t=ENGLISH_NEWS[n.id];const paragraphs=t?t.slice(1):["An English translation is pending editorial review; see the original source link."];const headline=t?.[0]||"Football News — English Translation Pending";const category=n.category==="team-player"?"Clubs & Players":n.category==="international"?"International Football":"Football News";return {...n,title:headline,paragraphs,content:paragraphs.join("\\n\\n"),categoryLabel:category,imageCaption:"Archive photograph ("+(n.imageDate||"date documented at source")+") · "+(n.imageCredit||n.sourceName||"source archive")+" · "+(n.imageLicense||"")+". Not a photograph of the current event.",imageAlt:"Editorial image for "+headline};})};return data}
window.fetch=async function(input,init){const response=await rawFetch(input,init);try{const address=typeof input==="string"?input:input?.url||String(input);const url=new URL(address,document.baseURI);if(url.origin!==location.origin||!/\/data\/(?:today\.json|(?:archive|fixtures|odds|news)\/.*\.json)$/.test(url.pathname)||!response.ok)return response;const original=await response.clone().json();const out=translate(original,url.pathname);const headers=new Headers(response.headers);headers.delete("content-length");headers.delete("content-encoding");return new Response(JSON.stringify(out),{status:response.status,statusText:response.statusText,headers})}catch(err){console.warn("Goal Zone English translation fallback",err);return response}};
